import{_ as i,a0 as o,w as s,s as p,ao as r,I as l,x as t,a1 as b,A as g}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"軟件 bug 的生命週期 | LCTT x X-CMD","titleTemplate":false,"description":"軟件 bug 的生命週期 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"軟件 bug 的生命週期 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"軟件 bug 的生命週期 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20180625 The life cycle of a software bug","title":"軟件 bug 的生命週期","tag":"201901","desc":""},"relativePath":"201901/20180625 The life cycle of a software bug.md","filePath":"[post].md"}'),a={name:"201901/20180625 The life cycle of a software bug.md"};function n(f,u,d,m,T,x){const e=o("Link");return s(),p("div",null,[u[25]||(u[25]=r('<h1 id="軟件-bug-的生命週期" tabindex="-1">軟件 bug 的生命週期 <a class="header-anchor" href="#軟件-bug-的生命週期" aria-label="Permalink to “軟件 bug 的生命週期”">​</a></h1><blockquote><p>從發現軟件故障到解決它們，這裏講述是開發團隊如何壓制軟件 bug。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/bug_software_issue_tracking_computer_screen.jpg?itok=6qfIHR5y" alt=""></p><p>1947 年，發現了第一個計算機 bug —— 被困在計算機繼電器中的飛蛾。</p><p>要是所有的 bug 都能如此簡單地發現就好了。隨着軟件變得越來越複雜，測試和調試的過程也變得更加複雜。如今，軟件 bug 的生命週期可能會很長，儘管正確的技術和業務流程可能會有所幫助。對於開源軟件，開發人員使用嚴格的工單服務和協作來查找和解決 bug。</p><h3 id="確認計算機-bug" tabindex="-1">確認計算機 bug <a class="header-anchor" href="#確認計算機-bug" aria-label="Permalink to “確認計算機 bug”">​</a></h3><p>在測試過程中，發現的 bug 會報告給開發團隊。質量保證測試人員儘可能詳細地描述 bug ，報告他們的系統狀態、他們正在進行的過程以及 bug 是如何表現出來的。</p><p>儘管如此，一些 bug 從未得到確認；它們可能會在測試中報告，但永遠無法在可控環境中重現。在這種情況下，它們可能得不到解決，而是被關閉。</p><p>有些計算機 bug 可能很難確認，因為使用的平台種類繁多，用户行為也非常多。有些 bug 只是間歇性地或在非常特殊的情況下發生的，而另一些 bug 可能會出現在隨機的情況下。</p><p>許多人使用開源軟件並與之交互，許多 bug 和問題可能是不可重複的，或者可能沒有得到充分的描述。不過，由於每個用户和開發人員也都扮演質量保證測試人員的角色，至少在一定程度上，bug 還是很有可能會發現的。</p><p>確認 bug 後，修復工作就開始了。</p><h3 id="分配要修復的-bug" tabindex="-1">分配要修復的 bug <a class="header-anchor" href="#分配要修復的-bug" aria-label="Permalink to “分配要修復的 bug”">​</a></h3><p>已確認的 bug 被分配給負責解決的開發人員或開發團隊。在此階段，需要重現 bug，發現問題，並修復相關代碼。如果 bug 的優先級較低，開發人員可以將此 bug 分類為稍後要修復的問題，也可以在該 bug 具有高優先級的情況下直接指派某人修復。無論哪種方式，都會在開發過程中打開一個工單，並且 bug 將成為已知的問題。</p>',13)),l("p",null,[u[1]||(u[1]=t("在開源解決方案中，開發人員可以進行選擇他們想要解決的 bug，要麼選擇他們最熟悉的程序區域，要麼從優先級最高的的開始。綜合解決方案，如 ",-1)),b(e,{href:"https://github.com/"},{default:g(()=>[...u[0]||(u[0]=[t("GitHub",-1)])]),_:1}),u[2]||(u[2]=t(" 使得多個開發人員能夠輕鬆地着手解決，而不會干擾彼此的工作。",-1))]),u[26]||(u[26]=r('<p>當將 bug 設置為需要修復時，bug 報告者還可以為該 bug 選擇優先級。主要的 bug 可能具有較高的優先級，而僅與外觀相關的 bug 可能具有較低的級別。優先級確定開發團隊解決這些問題的方式和時間。無論哪種方式，所有的 bug 都需要先解決，然後才能認為產品已完成。在這方面，適當的回溯到優先級高的需求也會很有幫助。</p><h3 id="解決-bug" tabindex="-1">解決 bug <a class="header-anchor" href="#解決-bug" aria-label="Permalink to “解決 bug”">​</a></h3><p>一旦修復了 bug ，通常會將其作為已解決的 bug 發送回質量保證測試人員。然後，質量保證測試人員再次將產品置於其工作中，以重現 bug。如果無法重現 bug ，質量保證測驗人員將假定它已得到適當解決。</p><p>在開源情況下，任何更改都會被分發，通常是作為正在測試的暫定版本。此測試版本分發給用户，用户再次履行質量保證測試人員的職責並測試產品。</p><p>如果 bug 再次出現，問題將被髮送回開發團隊。在此階段，該 bug 將重新觸發，開發團隊有責任重複解決該 bug 的循環。這種情況可能會發生多次，尤其是在 bug 不可預知或間歇性發生的情況下。眾所周知，間歇性的 bug 很難解決。</p><p>如果該 bug 不再出現，則該問題將被標記為已解決。在某些情況下，最初的 bug 得到了解決，但由於所做的更改，會出現其他 bug。發生這種情況時，可能需要新的 bug 報告，然後重新開始該過程。</p><h3 id="關閉-bug" tabindex="-1">關閉 bug <a class="header-anchor" href="#關閉-bug" aria-label="Permalink to “關閉 bug”">​</a></h3><p>在處理、識別和解決 bug 後，該 bug 將被關閉，開發人員可以轉到軟件開發和測試的其他階段。如果始終找不到 bug ，或者開發人員無法重現 bug ，則該 bug 也將被關閉 —— 無論哪種方式，都將開始開發和測試的下一階段。</p><p>在測試版本中對解決方案所做的任何更改都將滾動到產品的下一個版本中。如果 bug 是嚴重的，則在下一個版本發佈之前，可能會為當前用户提供修補程序或修補程序。這在安全問題中很常見。</p><p>軟件 bug 可能很難找到，但通過遵循過程，開發人員可以使開發更快、更容易、更一致。質量保證是這一過程的重要組成部分，因為質量保證測試人員必須發現和識別 bug ，並幫助開發人員重現這些 bug 。在 bug 不再發生之前，無法關閉和解決 bug。</p><p>開源的解決方案分散了質量保證測試、開發和緩解的負擔，這往往導致 bug 被更快、更全面地發現和緩解。但是，由於開源技術的性質，此過程的速度和準確性通常取決於解決方案的受歡迎程度及其維護和開發團隊的敬業精神。</p>',11)),l("p",null,[u[6]||(u[6]=t("Rich Butkevic 是一個 PMP 項目經理認證,，敏捷開發框架認證（certified scrum master） 並且 維護 ",-1)),b(e,{href:"https://projectzendo.com"},{default:g(()=>[...u[3]||(u[3]=[t("Project Zendo",-1)])]),_:1}),u[7]||(u[7]=t("，這是供項目管理專業人員去發現、簡化和改進其項目成果策略的網站。可以在 ",-1)),b(e,{href:"https://richbutkevic.com"},{default:g(()=>[...u[4]||(u[4]=[t("Richbutkevic.com",-1)])]),_:1}),u[8]||(u[8]=t(" 或者使用 ",-1)),b(e,{href:"https://www.linkedin.com/in/richbutkevic"},{default:g(()=>[...u[5]||(u[5]=[t("LinkedIn",-1)])]),_:1}),u[9]||(u[9]=t(" 與 Rich 聯繫。",-1))]),u[27]||(u[27]=l("hr",null,null,-1)),l("p",null,[u[11]||(u[11]=t("via: ",-1)),b(e,{href:"https://opensource.com/article/18/6/life-cycle-software-bug"},{default:g(()=>[...u[10]||(u[10]=[t("https://opensource.com/article/18/6/life-cycle-software-bug",-1)])]),_:1})]),l("p",null,[u[16]||(u[16]=t("作者：",-1)),b(e,{href:"https://opensource.com/users/rich-butkevic"},{default:g(()=>[...u[12]||(u[12]=[t("Rich Butkevic",-1)])]),_:1}),u[17]||(u[17]=t(" 選題：",-1)),b(e,{href:"https://github.com/lujun9972"},{default:g(()=>[...u[13]||(u[13]=[t("lujun9972",-1)])]),_:1}),u[18]||(u[18]=t(" 譯者：",-1)),b(e,{href:"https://github.com/lixinyuxx"},{default:g(()=>[...u[14]||(u[14]=[t("lixinyuxx",-1)])]),_:1}),u[19]||(u[19]=t(" 校對：",-1)),b(e,{href:"https://github.com/wxy"},{default:g(()=>[...u[15]||(u[15]=[t("wxy",-1)])]),_:1})]),l("p",null,[u[22]||(u[22]=t("本文由 ",-1)),b(e,{href:"https://github.com/LCTT/TranslateProject"},{default:g(()=>[...u[20]||(u[20]=[t("LCTT",-1)])]),_:1}),u[23]||(u[23]=t(" 原創編譯，",-1)),b(e,{href:"https://linux.cn/"},{default:g(()=>[...u[21]||(u[21]=[t("Linux中國",-1)])]),_:1}),u[24]||(u[24]=t(" 榮譽推出",-1))])])}const P=i(a,[["render",n]]);export{h as __pageData,P as default};
